def fail(message: str) -> None:
    raise SystemExit(
        f"ERREUR : {message}\nAucun fichier n'a été modifié."
    )


def get_method(source: str, name: str) -> str:
    lines = source.splitlines(keepends=True)
    start = None

    for index, line in enumerate(lines):
        if line.startswith(f"    def {name}("):
            start = index
            break

    if start is None:
        fail(f"méthode {name} introuvable")

    end = len(lines)
    for index in range(start + 1, len(lines)):
        if (
            lines[index].startswith("    def ")
            or lines[index].startswith("    @")
        ):
            end = index
            break

    return "".join(lines[start:end])


def replace_method(
    source: str,
    name: str,
    replacement: str,
) -> str:
    old = get_method(source, name)
    return source.replace(
        old,
        replacement.rstrip() + "\n\n",
        1,
    )


def main() -> None:
    if not TARGET.is_file():
        fail(f"fichier introuvable : {TARGET}")

    original = TARGET.read_text(encoding="utf-8")
    current = get_method(
        original,
        "_create_internal_navigation_ribbon",
    )

    if NEW_MARKER in current:
        print("BANDEAU_DECORATIF_V5_DEJA_APPLIQUE")
        return

    candidate = replace_method(
        original,
        "_create_internal_navigation_ribbon",
        NEW_METHOD,
    )

    try:
        compile(candidate, str(TARGET), "exec")
    except Exception as exc:
        fail(f"la nouvelle version ne compile pas : {exc}")

    backup_dir = PROJECT / "cache" / "correctifs"
    backup_dir.mkdir(parents=True, exist_ok=True)

    stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    backup = (
        backup_dir
        / f"document_view_avant_bandeau_v5_{stamp}.py"
    )
    temp = TARGET.with_suffix(".bandeau_v5.tmp")

    try:
        temp.write_text(candidate, encoding="utf-8")
        py_compile.compile(str(temp), doraise=True)
        shutil.copy2(TARGET, backup)
        temp.replace(TARGET)
        py_compile.compile(str(TARGET), doraise=True)
    except Exception as exc:
        try:
            temp.unlink(missing_ok=True)
        except Exception:
            pass

        if backup.exists():
            shutil.copy2(backup, TARGET)

        fail(
            f"installation annulée automatiquement : {exc}"
        )

    print("BANDEAU_DECORATIF_V5_OK")
    print("Accueil est maintenant juste avant Centre.")
    print("Visualisation et Suivi du livre restent à gauche.")
    print("Le fond editorial_bg_accueil est intégré et rendu visible dans le ruban.")
    print("Les icônes restent provisoires avant le futur jeu personnalisé.")
    print(f"Sauvegarde : {backup}")


if __name__ == "__main__":
    main()
